/* old sayings about health and movement: [title, source, meaning] */
sayings:[["An inch of length","A traditional saying","Lengthen the sinews an inch, and add ten years to your life."],
 ["Running water","A traditional saying","Running water never goes stale, and a door hinge never rots."],
 ["From the legs","A traditional saying","A person grows old from the legs first."],
 ["A hundred steps","A traditional saying","Walk a hundred steps after each meal and you will live to ninety-nine."],
 ["Every season","A traditional saying","Train in the deepest cold of winter and the fiercest heat of summer."]],
presence:{
 all:["Notice the soles of your feet on the ground.","Let the breath lead, and let the body follow.","Soften the jaw, and the space between the eyebrows.","If the mind has wandered, gently come back to the breath.","Feel the movement from the inside.","Move slowly enough to feel every part of it.","Notice any tension, and let it go on the out-breath.","Nowhere else to be. Just this movement, this breath.","Let the shoulders be heavy and the crown of the head light."],
 stretch:["Breathe into the place that is stretching.","With each out-breath, let the muscle release a little more.","Find the edge of the stretch, and rest there without pushing."],
 stance:["Feel the ground pushing back up through the legs.","Root down through the feet. Lengthen up through the crown.","Let the strength come from the legs while the upper body stays soft."],
 legs:["Feel the ground pushing back up through the legs."],
 balance:["Rest your gaze on one still point.","Small wobbles are fine. Keep returning to center."],
 breath:["Notice the cool air on the in-breath, and the warm air on the out-breath.","Let each breath be smooth, even and unhurried.","Rest your attention at the belly, just below the navel."],
 meditation:["Let the breath be just as it is.","Notice sounds around you, then return to the breath.","Awareness is like the sky. Thoughts are clouds passing through."],
 selfcare:["Notice the warmth and tingling where your hands have been.","Care for the body the way you would care for someone you love."],
 animals:["Let the spirit of the animal fill the movement.","Play. There is no wrong way to be the animal."],
 flow:["Breathe naturally, and let the breath find the rhythm of the movement.","Notice the breath without changing it.","Let each out-breath soften the movement a little."],
 soft:["Slow, deep breaths. Breathe in length, breathe out release.","Let the breath go to the place that is stretching.","Long, quiet breaths through the nose."]},
